from __future__ import annotations

import logging
import os

from artifact_tool_v2.spreadsheet_warmup import warm_spreadsheet_runtime

logger = logging.getLogger(__name__)

_SPREADSHEET_WARMUP_ENV = "CUA_DD_PYTHON_TOOL_WARM_SPREADSHEET_RUNTIME"
_TRUE_VALUES = frozenset({"1", "true", "yes", "on"})


def _env_is_true(name: str, default: bool = False) -> bool:
    raw = os.getenv(name)
    if raw is None:
        return default
    return raw.strip().lower() in _TRUE_VALUES


def warm_spreadsheet_runtime_on_startup() -> None:
    if not _env_is_true(_SPREADSHEET_WARMUP_ENV):
        return

    try:
        warm_spreadsheet_runtime()
    except Exception:
        logger.exception("Spreadsheet runtime warmup failed during python startup")


warm_spreadsheet_runtime_on_startup()
